// Cloudflare Worker loader for the OpenBao core compiled to Go js/wasm.
//
// This is a modified copy of the loader generated by
// `workers-assets-gen` from github.com/syumai/workers-go. The stock loader
// creates a fresh Go instance for *every request*, which is fine for a
// hello-world handler but would mean re-running OpenBao's unseal and mount
// setup (dozens of PostgreSQL round-trips) per request. Instead, this loader
// instantiates the Go program once per isolate and keeps it alive, so the
// in-memory core survives across requests until Cloudflare evicts the
// isolate.
//
// The Go side never closes its done channel (see wasm/worker/main.go: the
// handler is served with workers.Serve, whose Done channel is only closed
// by the stock per-request loader's body close; here we never let Go exit).

import "./wasm_exec.js";
import { createRuntimeContext, loadModule } from "./runtime.mjs";

let mod;
let goInstance; // { go, binding } once started
let starting;

globalThis.tryCatch = (fn) => {
  try {
    return { result: fn() };
  } catch (e) {
    return { error: e };
  }
};

async function start(env, ctx) {
  if (mod === undefined) {
    mod = await loadModule();
  }
  const binding = {};
  const go = new Go();
  let ready;
  const readyPromise = new Promise((resolve) => {
    ready = resolve;
  });
  const instance = new WebAssembly.Instance(mod, {
    ...go.importObject,
    workers: { ready: () => ready() },
  });
  // Note: env/ctx captured here are the *first* request's. env (vars,
  // secrets, Hyperdrive binding) is identical for every request in the
  // isolate; ctx.waitUntil is only valid for its own request and is not
  // used by the Go side.
  // Expose the linear memory so the Go side can report its true size (Go's
  // MemStats.Sys excludes the data segment).
  globalThis.__wasmMemory = instance.exports.mem;
  go.run(instance, createRuntimeContext({ env, ctx, binding }));
  await readyPromise;
  return { go, binding };
}

async function ensureStarted(env, ctx) {
  if (goInstance) return goInstance;
  if (!starting) {
    starting = start(env, ctx).then(
      (inst) => {
        goInstance = inst;
        return inst;
      },
      (err) => {
        starting = undefined;
        throw err;
      },
    );
  }
  return starting;
}

async function fetch(req, env, ctx) {
  const { binding } = await ensureStarted(env, ctx);
  return binding.handleRequest(req);
}

export default { fetch };
